package io.aetheris.orchestrator.api;import io.aetheris.orchestrator.voice.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/orchestrator/stage8/voice") public class VoiceStreamingController {private final VoiceStreamingService service;public VoiceStreamingController(VoiceStreamingService service){this.service=service;}@GetMapping("/adapters") public Map<String,Object> adapters(){return service.adapters();}@PostMapping("/metrics") public VoiceTurnMetricEntity metrics(@RequestBody VoiceTurnMetricRequest r){return service.record(r);}@GetMapping("/metrics") public List<VoiceTurnMetricEntity> metrics(){return service.recent();}}
